SELECT tab.* FROM ( SELECT lcr.*, (CASE WHEN (lcr.confirm_flag = 'Y') THEN '已确认' ELSE '未确认' END) confirm_flag_n, lcw.due_amount withdraw_due_amount, lc.major_contract_number, lcw.withdraw_number, (select fc.currency_name from fnd_currency fc where fc.currency_code = lc.currency) currency_name, ( SELECT hct.description FROM hls_cashflow_type hct WHERE hct.cf_type = lcr.cf_type AND hct.enabled_flag = 'Y' ) cf_type_desc, ( SELECT description FROM hls_cashflow_item hci WHERE hci.cf_type = lcr.cf_type AND hci.cf_item = lcr.cf_item AND hci.enabled_flag = 'Y' ) cf_item_desc, ( SELECT description FROM hls_cashflow_item hci WHERE hci.cf_type = lcr.cf_type AND hci.cf_item = lcr.cf_item AND hci.enabled_flag = 'Y' ) cf_item_n, ROUND((nvl(lcr.exchange_rate,1)*lcr.planned_due_amount),2) cny_planned_due_amount, (SELECT scv.meaning FROM
scv WHERE scv.code_value = lcr.write_off_flag AND scv.code = 'LON.WRITE_OFF_FLAG' ) write_off_flag_desc, ( lcr.due_amount - nvl(lcr.write_off_amount, 0) ) AS remainPaybackAmount, (select contract_number from lon_contract lc where lc.contract_id = lcr.contract_id)as contract_number, (select contract_name from lon_contract lc where lc.contract_id = lcr.contract_id)as contract_name, (select hbm.bp_name from hls_bp_master hbm,lon_contract lc where hbm.bp_id = lc.credit_bp_id and lc.contract_id = lcr.contract_id )as bp_name FROM lon_contract lc, lon_contract_repayment lcr, lon_contract_withdraw lcw
lcr.withdraw_id = lcw.withdraw_id and lcw.contract_id = lc.contract_id and lc.data_class = 'NORMAL'
and lcr.repayment_id = #{repaymentId}
AND lcr.withdraw_id = #{withdrawId}
and lcw.data_class='NORMAL'
AND lcr.contract_id = #{contractId}
and ((#{interestFlag} = 'Y' and lcr.cf_item in (301,302)) or (#{interestFlag} = 'N' and lcr.cf_item not in (301,302)))
AND lcr.repayment_id IN
#{item}
ORDER BY lcr.times,lcr.planned_due_date,lcr.cf_item) tab where tab.withdraw_number is not null

SELECT tab.* FROM ( SELECT lcr.*, ( SELECT s.MEANING value_name FROM sys_code_value_b_v s WHERE s.CODE = 'FIN.SERVER_AMORTIZATION_METHOD' AND s.code_value = lcr.amortization_method ) AS amortization_method_n, lcw.due_amount withdraw_due_amount, lc.major_contract_number, lcw.withdraw_number, (select fc.currency_name from fnd_currency fc where fc.currency_code = lc.currency) currency_name, (select v.meaning from sys_code_value_b_v v where v.code = 'LON.SERVICE_FEE_PAYMENT_METHOD' and v.code_value = lcr.payment_method) as payment_method_n, ( SELECT hct.description FROM hls_cashflow_type hct WHERE hct.cf_type = lcr.cf_type AND hct.enabled_flag = 'Y' ) cf_type_desc, ( SELECT description FROM hls_cashflow_item hci WHERE hci.cf_type = lcr.cf_type AND hci.cf_item = lcr.cf_item AND hci.enabled_flag = 'Y' ) cf_item_desc, ( SELECT description FROM hls_cashflow_item hci WHERE hci.cf_type = lcr.cf_type AND hci.cf_item = lcr.cf_item AND hci.enabled_flag = 'Y' ) cf_item_n, ROUND((nvl(lcr.exchange_rate,1)*lcr.planned_due_amount),2) cny_planned_due_amount, (SELECT scv.meaning FROM
scv WHERE scv.code_value = lcr.write_off_flag AND scv.code = 'LON.WRITE_OFF_FLAG' ) write_off_flag_desc, ( lcr.due_amount - nvl(lcr.write_off_amount, 0) ) AS remainPaybackAmount, (select contract_number from lon_contract lc where lc.contract_id = lcr.contract_id)as contract_number, (select contract_name from lon_contract lc where lc.contract_id = lcr.contract_id)as contract_name, (select hbm.bp_name from hls_bp_master hbm,lon_contract lc where hbm.bp_id = lc.credit_bp_id and lc.contract_id = lcr.contract_id )as bp_name FROM lon_contract lc, lon_contract_repayment lcr, lon_contract_withdraw lcw
lcr.withdraw_id = lcw.withdraw_id and lcw.contract_id = lc.contract_id and lc.data_class = 'NORMAL'
and lcr.repayment_id = #{repaymentId}
AND lcr.withdraw_id = #{withdrawId}
and lcw.data_class='NORMAL'
AND lcr.contract_id = #{contractId}
and ((#{interestFlag} = 'Y' and lcr.cf_item not in (301,302)) or (#{interestFlag} = 'N' and lcr.cf_item not in (310)))
AND lcr.repayment_id IN
#{item}
ORDER BY lcr.PLANNED_DUE_DATE,lcr.times,lcr.cf_item ) tab where tab.withdraw_number is not null

select lcr.*,
(select lcw.withdraw_number from lon_contract_withdraw lcw
where lcw.withdraw_id = lcr.withdraw_id) withdraw_number,
(select hci.description from hls_cashflow_item hci
where hci.cf_type = 70
and hci.cf_item = lcr.cf_item) cf_item_desc
from lon_contract_repayment lcr

    lcr.withdraw_id = #{withdrawId}

        and lcr.cf_item = #{cfItem}


        and ((#{interestFlag} = 'Y' and lcr.cf_item in (301,302)) or (#{interestFlag} = 'N' and lcr.cf_item not
        in (301,302)))


        and lcr.confirm_flag = #{confirmFlag}


        and lcr.write_off_flag = #{writeOffFlag}


        and lcr.is_system_flag = #{isSystemFlag}


        and lcr.planned_calc_date > #{startDay}


        and lcr.planned_calc_date < #{endDay}

    order by lcr.planned_due_date

SELECT concat( YEAR (lcr.planned_due_date), '年', MONTH (lcr.planned_due_date), '月' ) as period, ((YEAR(lcr.planned_due_date)-YEAR(sysdate))*12+(MONTH(lcr.planned_due_date)-MONTH(sysdate))) as remanning_times, sum(lcr.planned_due_amount-nvl(lcr.write_off_amount,0)) as reimbursement_amount FROM lon_contract_repayment lcr WHERE lcr.planned_due_date > sysdate GROUP BY period ORDER BY YEAR (lcr.planned_due_date),MONTH (lcr.planned_due_date)
AND remanning_times <= 12
AND remanning_times >= 13
AND reimbursement_amount >=#{amtFrom}
AND reimbursement_amount <=#{amtTo}

select lcr.*, (select lcw.withdraw_number from lon_contract_withdraw lcw where lcw.withdraw_id = lcr.withdraw_id) withdraw_number, (select hci.description from hls_cashflow_item hci where hci.cf_type = 70 and hci.cf_item = lcr.cf_item) cf_item_desc from lon_contract_repayment lcr
lcr.withdraw_id = #{withdrawId} and lcr.planned_due_date>= #{startDay} and lcr.planned_due_date<= #{endDay}
and lcr.cf_item = #{cfItem}
and ((#{interestFlag} = 'Y' and lcr.cf_item in (301,302)) or (#{interestFlag} = 'N' and lcr.cf_item not in (301,302)))
and lcr.confirm_flag = #{confirmFlag}
order by lcr.planned_due_date

select lcr.*,
(select lcw.withdraw_number from lon_contract_withdraw lcw
where lcw.withdraw_id = lcr.withdraw_id) withdraw_number,
(select hci.description from hls_cashflow_item hci
where hci.cf_type = 70
and hci.cf_item = lcr.cf_item) cf_item_desc
from lon_contract_repayment lcr

    lcr.withdraw_id = #{withdrawId}

        and lcr.cf_item =301


        and lcr.planned_due_date>=#{startDay}
        and #{endDay}>=lcr.planned_due_date



        and lcr.cf_item = #{cfItem}


        and lcr.confirm_flag = #{confirmFlag}


        and lcr.is_system_flag=#{isSystemFlag}

    order by lcr.planned_due_date

select lcr.*,
(select lcw.withdraw_number from lon_contract_withdraw lcw
where lcw.withdraw_id = lcr.withdraw_id) withdraw_number,
(select hci.description from hls_cashflow_item hci
where hci.cf_type = 70
and hci.cf_item = lcr.cf_item) cf_item_desc
from lon_contract_repayment lcr

    lcr.withdraw_id = #{withdrawId}
    and lcr.planned_due_date>=#{startDay} and lcr.planned_due_date<#{endDay}

        and lcr.cf_item = #{cfItem}


        and lcr.cf_item =302


        and lcr.confirm_flag = #{confirmFlag}

    order by lcr.planned_due_date

mapper.update:
update lon_contract_repayment t
set t.planned_due_amount=(nvl(t.planned_due_amount,0)-(select nvl(sum(nvl(lr.planned_due_amount,0)),0)
                                                       from lon_contract_repayment lr
                                                       where lr.planned_due_date>#{startDay}
                                                             and lr.planned_due_date<#{endDay}
                                                             and lr.withdraw_id = #{withdrawId}
                                                             and lr.cf_item= #{cfItem}))
   where t.planned_due_date=#{endDay}
         and t.withdraw_id = #{withdrawId}
         and t.cf_item= #{cfItem}

mapper.select:
select sum(round(t.planned_due_amount*nvl(t.exchange_rate,1),2)) as sumAmount
from lon_contract_repayment t
where t.cf_item=#{cfItem}
and t.WITHDRAW_ID=#{withdrawId}

select nvl(sum(t.PLANNED_DUE_AMOUNT),0) as sumAmount from lon_contract_repayment t
where t.cf_item=310
and t.WITHDRAW_ID=#{withdrawId}

select nvl(sum(t.PLANNED_DUE_AMOUNT),0) as sumAmount from lon_contract_repayment t
where t.cf_item in(301,310)
and t.WITHDRAW_ID=#{withdrawId} and planned_due_date between #{incomeDate} and #{incomeEndDate}

select nvl(sum(t.PLANNED_DUE_AMOUNT),0) as sumAmount from lon_contract_repayment t
where t.cf_item=302
and t.IS_SYSTEM_FLAG='N'
and t.WITHDRAW_ID=#{withdrawId}
and t.planned_due_date between #{startDay} and #{endDay}

SELECT tab.* FROM ( SELECT lcr.*, lcw.due_amount withdraw_due_amount, lc.major_contract_number, lcw.withdraw_number, (select fc.currency_name from fnd_currency fc where fc.currency_code = lc.currency) currency_name, ( SELECT hct.description FROM hls_cashflow_type hct WHERE hct.cf_type = lcr.cf_type AND hct.enabled_flag = 'Y' ) cf_type_desc, ( SELECT description FROM hls_cashflow_item hci WHERE hci.cf_type = lcr.cf_type AND hci.cf_item = lcr.cf_item AND hci.enabled_flag = 'Y' ) cf_item_desc, ROUND((nvl(lcr.exchange_rate,1)*lcr.planned_due_amount),2) cny_planned_due_amount, (SELECT scv.meaning FROM
scv WHERE scv.code_value = lcr.write_off_flag AND scv.code = 'LON.WRITE_OFF_FLAG' ) write_off_flag_desc, ( lcr.due_amount - nvl(lcr.write_off_amount, 0) ) AS remainPaybackAmount, (select contract_number from lon_contract lc where lc.contract_id = lcr.contract_id)as contract_number, (select contract_name from lon_contract lc where lc.contract_id = lcr.contract_id)as contract_name, (select hbm.bp_name from hls_bp_master hbm,lon_contract lc where hbm.bp_id = lc.credit_bp_id and lc.contract_id = lcr.contract_id )as bp_name FROM lon_contract lc, lon_contract_repayment lcr, lon_contract_withdraw lcw
lcr.withdraw_id = lcw.change_req_id and lcw.contract_id = lc.contract_id and lc.data_class = 'NORMAL'
and lcr.repayment_id = #{repaymentId}
AND lcr.withdraw_id = #{withdrawId}
and lcw.data_class='NORMAL'
AND lcr.contract_id = #{contractId}
and ((#{interestFlag} = 'Y' and lcr.cf_item in (301,302)) or (#{interestFlag} = 'N' and lcr.cf_item not in (301,302)))
AND lcr.repayment_id IN
#{item}
ORDER BY lcr.cf_item ,lcr.times) tab where tab.withdraw_number is not null

select t.* from (SELECT lcr.repayment_id, lcr.withdraw_id, lcr.contract_id, lcr.times, lcr.cf_item, lcr.cf_type, lcr.cf_direction, lcr.cf_status, lcr.planned_due_date, lcr.planned_due_amount, lcr.due_date, lcr.due_amount, lcr.write_off_flag, lcr.write_off_amount, lcr.interest_period_days, lcr.interest_accrual_balance, lcr.relate_contract_id, lcr.rent_due_date, lcr.rent_due_amount, lcr.relate_contract_category, lcr.group_id, lcr.group_number, lcr.object_version_number, lcr.request_id, lcr.program_id, lcr.created_by, lcr.creation_date, lcr.last_updated_by, lcr.last_update_date, lcr.last_update_login, lcr.exchange_rate, lcr.retain_amount, lcr.is_system_flag, lcr.planned_calc_date, lcr.received_bank_account_name, lcr.received_bp_name, lcr.cny_due_amount, lcr.confirm_flag, lcr.received_bank_account_num, lcr.contract_type, lcr.amortization_method, (select s.description from sys_user s where s.user_id = lcr.created_by) created_by_n, (CASE WHEN (lcr.confirm_flag = 'Y') THEN '已确认' ELSE '未确认' END) confirm_flag_n, lcw.due_amount withdraw_due_amount, lc.major_contract_number, lcw.withdraw_number, (select fc.currency_name from fnd_currency fc where fc.currency_code = lc.currency) currency_name, ( SELECT hct.description FROM hls_cashflow_type hct WHERE hct.cf_type = lcr.cf_type AND hct.enabled_flag = 'Y' ) cf_type_desc, ( SELECT description FROM hls_cashflow_item hci WHERE hci.cf_type = lcr.cf_type AND hci.cf_item = lcr.cf_item AND hci.enabled_flag = 'Y' ) cf_item_desc, ( SELECT description FROM hls_cashflow_item hci WHERE hci.cf_type = lcr.cf_type AND hci.cf_item = lcr.cf_item AND hci.enabled_flag = 'Y' ) cf_item_n, ROUND((nvl(lcr.exchange_rate,1)*lcr.planned_due_amount),2) cny_planned_due_amount, (SELECT scv.meaning FROM sys_code_value_b_v scv WHERE scv.code_value = lcr.write_off_flag AND scv.code = 'LON.WRITE_OFF_FLAG' ) write_off_flag_desc, ( lcr.due_amount - nvl(lcr.write_off_amount, 0) ) AS remainPaybackAmount, (select contract_number from lon_contract lc where lc.contract_id = lcr.contract_id)as contract_number, (select contract_name from lon_contract lc where lc.contract_id = lcr.contract_id)as contract_name, (select document_type from lon_contract lc where lc.contract_id = lcr.contract_id)as document_type, (select scv.MEANING from lon_contract lc,sys_code_b sc,sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'FIN.CREDIT_METHOD' and scv.value = lc.document_type and lc.contract_id = lcr.contract_id) as document_type_desc, lc.credit_bp_id, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = lc.credit_bp_id ) credit_bp_name, lcw.due_date withdraw_date, lcw.int_rate withdraw_int_rate, lcw.withdraw_end_date, lcw.with_bank_account_id, lcw.with_bank_account_name as with_bank_account_id_n, lcw.with_bank_account_num, lcw.with_bank_account_name, lcw.with_bank_branch_name, lc.currency, (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb where scb.code = 'CHS.CURRENCY_TYPE' and scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scvb.value = lc.currency) as currency_n, lc.lon_company_id, (select fc.company_full_name from fnd_company fc where fc.company_id = lc.lon_company_id) lon_company_id_n, --to_char(lcr.planned_calc_date, 'YYYY-MM-DD') - to_char(SYSDATE, 'YYYY-MM-DD') as to_repay_days, lc.finance_amount, lcw.due_amount as due_amount_new, lcw.auto_write FROM lon_contract lc, lon_contract_repayment lcr, lon_contract_withdraw lcw where lcr.withdraw_id = lcw.withdraw_id and lcw.contract_id = lc.contract_id and lc.data_class = 'NORMAL' and lcw.data_class='NORMAL' and lcw.withdraw_status = 'APPROVED' and lcr.cf_item in (301,302,303,304) and lcr.contract_type = 'IN' and lcr.write_off_flag = 'NOT' and lcw.withdraw_number is not null and not exists (select lcrbl.batch_ln_id from lon_con_repayment_batch lcrb, lon_con_repayment_batch_ln lcrbl where lcrbl.repayment_id = lcr.repayment_id and lcrb.batch_id = lcrbl.batch_id and lcrb.batch_status not in ('CANCEL')) ORDER BY lcr.planned_due_date,/*lc.credit_bp_id,lcw.withdraw_id, lcr.cf_item ,*/lcr.times) t
and t.planned_due_date = #{plannedDueDate}
and t.credit_bp_name like concat('%',concat(#{creditBpName},'%'))
and t.planned_due_date > #{plannedDueDateFrom}
and t.planned_due_date < #{plannedDueDateTo}
and t.currency = #{currency}
and t.lon_company_id = #{lonCompanyId}
and t.document_type = #{documentType}
and t.withdraw_number = #{withdrawNumber}
and t.withdraw_due_amount = #{withdrawDueAmount}
and to_char(t.withdraw_date,'yyyy-MM-dd') = to_char(to_date(#{withdrawDate},'yyyy-MM-dd'),'yyyy-MM-dd')
and to_char(t.withdraw_end_date,'yyyy-MM-dd') = to_char(to_date(#{withdrawEndDate},'yyyy-MM-dd'),'yyyy-MM-dd')
and t.cf_item = #{cfItem}
and t.to_repay_days <= #{toRepayDays}
and t.planned_calc_date >= to_date(#{plannedCalcDateFrom}, 'yyyy-mm-dd')
and t.planned_calc_date <= to_date(#{plannedCalcDateTo}, 'yyyy-mm-dd')
and t.auto_Write = #{autoWrite}
and created_by_n like #{createdByN}
and to_char(planned_calc_date, 'yyyymmdd') = to_char(#{plannedCalcDate},'yyyymmdd')

select  tt.interest_accrual_balance
from  lon_contract_repayment  tt
where tt.cf_item=#{cfItem}
and tt.WITHDRAW_ID=#{withdrawId}
and tt.times = #{times}-1

select  to_char(tt.planned_calc_date,'YYYY-MM-DD')   PLANNED_DUE_DATE_START
from  lon_contract_repayment  tt
where tt.cf_item=#{cfItem}
and tt.WITHDRAW_ID=#{withdrawId}
and tt.times = #{times}-1

select tt.*, to_char(tt.planned_calc_date,'YYYY-MM-DD')   PLANNED_DUE_DATE_end
from  lon_contract_repayment  tt
where
 tt.WITHDRAW_ID=#{withdrawId}

    and tt.cf_item = #{cfItem}


    and tt.times >= #{times}

order by tt.times+0
